    m[8] = ca * sb - sa * cc * cb;  m[9] = -sc * cb; m[10] = sa * sb + ca * cc * cb;  m[11] = 0;
    m[12] = px - (m[0] * px + m[4] * py + m[8] * pz);
    m[13] = py - (m[1] * px + m[5] * py + m[9] * pz);
    m[14] = pz - (m[2] * px + m[6] * py + m[10] * pz);
    m[15] = 1;
  }
  function mirarObjetivos(dt) {
    var ests = (mc && mc.structures) || null;
    if (!ests) return;
    mirones.length = 0;
    var p = mc.pos;
    for (var i = 0; i < ests.length; i++) {
      var s = ests[i], cfg = tabla[s.key];
      if (!cfg || !cfg.mirar) {
        if (s.model) { s.model = null; s._mirarYaw = 0; s._mirarPit = 0; }   // dejo de mirar: a su pose horneada
        continue;
      }
      mirones.push(s);
      var L = cfg.mirar, a = s.aabb;
      if (!a) continue;                  // instancia a medio construir: se la salta, no se tumba el frame
      // Por donde se engancha: el centro de su caja salvo que la config diga otra cosa. El punto
      // que sale de aqui es el UNICO que no se mueve al girar, asi que es literalmente la
      // articulacion.
      var px, py, pz;
      if (L.piv) { puntoPivote(a, s.rot & 3, L.piv, pivXYZ); px = pivXYZ[0]; py = pivXYZ[1]; pz = pivXYZ[2]; }
      else { px = (a[0] + a[3]) * 0.5; py = (a[1] + a[4]) * 0.5; pz = (a[2] + a[5]) * 0.5; }
      var tx, ty, tz;
      if (L.objetivo === 'jugador') { tx = p[0]; ty = p[1]; tz = p[2]; }
      else { tx = L.objetivo[0]; ty = L.objetivo[1]; tz = L.objetivo[2]; }
      var dx = tx - px, dy = ty - py, dz = tz - pz;
      var horiz = Math.sqrt(dx * dx + dz * dz);
      // El angulo se mide DESDE la pose ya horneada (yaw = rot&3, cuartos de vuelta), que es lo que
      // hace que 'limites' signifique «grados desde su orientacion de origen» y no desde el norte.
      var horneado = (s.rot & 3) * 90 + L.frente;
      // «No mirar» tiene DOS motivos y los dos acaban igual: la pieza vuelve a su pose de origen.
      // El segundo se olvidaba, y se quedaba clavada en su tope mirando a la pared para siempre.
      var giroObj = 0, cabObj = 0;
      var rendida = (horiz * horiz + dy * dy) > L.alcance * L.alcance;   // 1) demasiado lejos
      if (!rendida) {
        var crudo = wrap180((Math.atan2(dx, -dz) / GRADO - horneado) * L.senY);
        giroObj = pinza(crudo, L.limY[0], L.limY[1]);
        // 2) no puede girar tanto: le has salido por detras. Quedarse en el tope es la postura de un
        // maniqui; rendirse y volver a su sitio es lo que hace un cuello.
        if (giroObj !== crudo) { rendida = true; giroObj = 0; }
        // El CABECEO no se cuenta como rendirse: llegar al tope del cuello mirando hacia arriba es
        // seguir mirandote, y si contara, pegar un salto le apagaria la cabeza entera de golpe.
        else if (L.ejes === 'xy') cabObj = pinza(Math.atan2(dy, horiz) / GRADO * L.senX, L.limX[0], L.limX[1]);
      }
      // Suavizado exponencial (mismo criterio que el resto del snippet: exp(-dt/tau), o sea igual a
      // 30 que a 120 fps). El giro se interpola por el camino CORTO, si no, ir de 179 a -179 daria
      // una vuelta entera de mas justo cuando pasas por detras.
      var k = L.suavidad > 0 ? 1 - Math.exp(-dt / L.suavidad) : 1;
      var giro = (typeof s._mirarYaw === 'number') ? s._mirarYaw + wrap180(giroObj - s._mirarYaw) * k : giroObj;
      var cab = (typeof s._mirarPit === 'number') ? s._mirarPit + (cabObj - s._mirarPit) * k : cabObj;
      giro = wrap180(giro);          // acotado: si no, dar vueltas lo aleja de sus 'limites' para siempre
      s._mirarYaw = giro; s._mirarPit = cab;
      // Ya rendida y ya en reposo: se quita la matriz en vez de dejar una identidad puesta, y
      // asi app.js vuelve a su camino de siempre (sin uniform y sin inflar la caja de culling).
      if (rendida && Math.abs(giro) < 0.05 && Math.abs(cab) < 0.05) {
        s._mirarYaw = 0; s._mirarPit = 0; if (s.model) s.model = null;
        continue;
      }
