    }
  }
  function mirones_() {
    var filas = mirones.map(function (s) {
      return { clave: s.key, celda: s.ox + ',' + s.oy + ',' + s.oz,
               giro: Math.round(s._mirarYaw || 0) + '°',
               cabeceo: Math.round(s._mirarPit || 0) + '°',
               activa: !!s.model };
    });
    if (!filas.length) console.log('game.bloques: ninguna pieza tiene "mirar" (o el Mundo no esta abierto).');
    else if (console.table) console.table(filas); else console.log(filas);
    return filas;
  }

  // ── Subida suave de escalones: el CUERPO da el salto, el OJO lo alcanza ──────────────────────
  // app.js sube los escalones de golpe (mcMoveAxis: p[1] += h dentro del mismo frame), asi que al
  // andar por una escalera de 8 voxels la camara teletransporta y+0,5 de una vez y se ve a saltos.
  // Es lo mismo que hace Minecraft, y Minecraft lo tapa igual que aqui: la fisica NO se toca (el
  // juego sigue igual de firme, misma colision y mismo alcance de escalon), solo se PINTA al jugador
  // un poco mas abajo y ese retraso se consume en ~0,1 s.
  //
  // Como el ojo se calcula en seis sitios distintos de app.js a partir de mc.pos[1], el desfase se
  // aplica sobre mc.pos[1] al SALIR del frame y se deshace al ENTRAR en el siguiente: entre medias
  // solo hay dibujado, y toda la fisica corre siempre sobre la y de verdad.
  //
  // El estado vive en mc (no en un closure) a proposito: si se reejecuta el snippet, el envoltorio
  // nuevo hereda el desfase que dejo el viejo en vez de dejar al jugador medio bloque hundido.
  function restaurarPaso() {
    var d = mc._pasoDesfase || 0;
    if (!d) return;
    // Si la y no es la que dejamos pintada, es que alguien movio al jugador por su cuenta
    // (game.tp, un respawn, un alPisar…): ese desfase ya no significa nada y se tira.
    // Se repone la y GUARDADA, no pos[1]+d: sumar y restar el desfase no da exactamente el mismo
    // float, y ese pelo de diferencia acabaria en la colision. Asi la fisica es idéntica al bit.
    if (mc._pasoY === mc.pos[1]) mc.pos[1] = mc._pasoReal; else mc._pasoDesfase = 0;
  }

  // El escalon se mide DONDE SE DA: dentro de mcMoveAxis, cuyo unico efecto sobre la y es el
  // `p[1] += h` del auto-escalon (app.js:4919), y cuyos dos unicos llamantes son las dos lineas
  // horizontales de mcUpdate. Deducirlo al final del frame comparando la y NO funciona, y fue el
  // primer intento: en app.js la gravedad va ANTES del horizontal, asi que el frame del escalon
  // termina con vel[1]=0 y `ny === p[1]`, no choca y deja **onGround = false** (app.js:5097). Una
  // guarda que pidiese «estar en el suelo» se apaga justo en el unico frame que hay que suavizar —
  // el dueño no notaba ninguna diferencia entre pasoSuave(0) y pasoSuave(1000). Midiendo aqui no hay
  // heuristica: saltar y trepar no pasan por mcMoveAxis, asi que no se cuelan solos.
  function envolverMoveAxis() {
    if (typeof mcMoveAxis !== 'function') return false;
    var orig = mcMoveAxis._paso ? mcMoveAxis._orig : mcMoveAxis;
    var env = function (ai, target) {
      var y0 = mc.pos[1];
      orig(ai, target);
      var d = mc.pos[1] - y0;
      if (d > 0) mc._pasoSubido = (mc._pasoSubido || 0) + d;
    };
    env._paso = VERSION;
    env._orig = orig;
    window.mcMoveAxis = env;
    return true;
  }

  function suavizarPaso(dt) {
    var d = mc._pasoDesfase || 0;
    var subido = mc._pasoSubido || 0;                   // lo que el auto-escalon levanto este frame
    mc._pasoSubido = 0;
    var tope = PASO * (mc.scale || 1);
    if (TAU_PASO > 0) {
      d += subido;                                      // el ojo se queda donde estaba
      d *= Math.exp(-dt / TAU_PASO);                    // independiente de los fps
      if (d > tope) d = tope;                           // nunca mas de un escalon por detras
      if (d < 1 / 512) d = 0;                           // menos de eso no se ve: se cierra en seco
    } else {
      d = 0;
    }
    mc._pasoDesfase = d;
    if (d) { mc._pasoReal = mc.pos[1]; mc.pos[1] -= d; mc._pasoY = mc.pos[1]; }
  }

  // ── Deslizamiento: seguir patinando al soltar las teclas (el hielo de Minecraft) ─────────────
  // Esto NO se puede hacer dejando puesta mc.vel, y ahi esta el motivo de que el patinaje se conduzca
  // a mano: en el suelo app.js:5094 REESCRIBE vel[0]/vel[2] cada frame desde las teclas, y sin teclas
  // los pone a cero ANTES de mover. Cualquier velocidad que dejemos puesta se borra al frame siguiente
  // sin haber movido nada (por eso 'inercia' es de RAPIDEZ y no de patinaje). Asi que aqui se guarda
  // la marcha llevada (mc._deslizVel), decae con exp(-dt/tau) —igual a 30 que a 120 fps— y se avanza
  // con el MISMO mcMoveAxis que usa app.js, para que muros y auto-escalon se comporten identico.
  // El estado vive en mc y no en una closure para que reejecutar el snippet no te congele a medio derrape.
  // ¿Se esta pilotando? Las mismas cuatro teclas que lee app.js:5086-5089 para fijar la velocidad.
  function hayRumbo() {
    var k = mc.keys || {};
    return !!(k['w'] || k['a'] || k['s'] || k['d']);
  }
  function deslizar(dt) {
    if (!mc.pos || !mc.vel) return;
    var llev = mc._deslizVel;
    if (agarradoPrev) { mc._deslizVel = null; return; }    // colgado de una escalera no se patina
    if (!mc.onGround) {
      // En el aire app.js ya conserva la inercia el solo (air-strafe, app.js:5096): no hay nada que
      // conducir. Solo se sigue la velocidad real para que al aterrizar se retome el derrape.
      if (llev) { llev[0] = mc.vel[0]; llev[1] = mc.vel[2]; }
      return;
    }
    var pie = pieEn();
    var tau = (pie && pie.m && pie.m.cfg && pie.m.cfg.deslizamiento) || 0;
    // Con una tecla de rumbo pulsada MANDA app.js: ya ha fijado vel y ya ha MOVIDO al jugador este
    // frame, asi que empujar aqui ademas seria moverlo DOS VECES. Eso se notaba como un aceleron al
    // salir de una pista rapida con W pulsada (el dueño lo vio y lo achaco al roce): durante los
    // ~3·TAU_ROCE del derrape ibas a marcha normal MAS la marcha guardada. Encima del bloque se
    // memoriza la marcha para cuando sueltes; fuera se olvida, que ahi ya no hay nada que patinar.
    if (hayRumbo()) {
      mc._deslizVel = tau > 0 ? [mc.vel[0], mc.vel[2]] : null;
      return;
    }
    if (!llev) return;             // nunca se CREA marcha fuera del hielo: andar normal no se toca
    // Ya fuera del hielo el derrape no se corta en seco (te sales patinando) pero dura un suspiro:
    // TAU_ROCE. Encima del hielo manda el tau del propio bloque.
    var k = Math.exp(-dt / (tau > 0 ? tau : TAU_ROCE));
    var nx = llev[0] * k, nz = llev[1] * k;
    if (Math.hypot(nx, nz) < DESLIZ_MIN) { mc._deslizVel = null; return; }
    var p = mc.pos;
    if (nx) { var x0 = p[0]; mcMoveAxis(0, x0 + nx * dt); if (p[0] === x0) nx = 0; }   // muro: ese eje muere
    if (nz) { var z0 = p[2]; mcMoveAxis(2, z0 + nz * dt); if (p[2] === z0) nz = 0; }
    if (!nx && !nz) { mc._deslizVel = null; return; }
    mc._deslizVel = [nx, nz];
    mc.vel[0] = nx; mc.vel[2] = nz;   // asi saltar (o pisar un trampolin) se lleva la marcha del derrape
  }

  // ── Instalacion: un unico envoltorio, SIEMPRE el de esta ejecucion ───────────────────────────
  // No apilar envoltorios sigue siendo obligatorio (apilarlos duplicaria la velocidad de trepado en
  // cada pasada), pero NO basta con no reinstalar: el envoltorio viejo se quedaba con SUS closures, y
  // sobre todo con SU tabla de materiales. Reejecutar el snippet creaba una tabla nueva que la fisica
  // no leia jamas, asi que todo lo definido a partir de ahi salia en lista()/info() y no hacia
  // absolutamente nada en el mundo (el dueño lo vio con un trampolin: la consola decia «impulso ↑12»
  // y el bloque no lanzaba). Lo correcto es DESENVOLVER el viejo por su _orig y volver a envolver.
  var previo = (typeof mcUpdate === 'function' && mcUpdate._bloques) ? mcUpdate : null;
  var yaEstaba = !!previo;
  if (typeof mcUpdate !== 'function') {
    console.warn('game.bloques: no encuentro mcUpdate; ¿es esta la pestaña del Mundo?');
  } else {
    var orig = previo ? previo._orig : mcUpdate;
    var envuelto = function (dt) {
      restaurarPaso();                                  // la fisica SIEMPRE arranca en la y de verdad
      var pieAntes = pieEn();
      var agarre = sondearAgarre();                       // ANTES de mover: la gravedad aun no se aplico
      var posAntes = mc.pos ? [mc.pos[0], mc.pos[1], mc.pos[2]] : null;
      // La velocidad horizontal con la que se ENTRA al frame. Hay que leerla aqui porque en el suelo
      // app.js la reescribe entera dentro de orig(dt); despues ya no queda ni rastro de la inercia.
      var velAntes = mc.vel ? [mc.vel[0], mc.vel[2]] : null;
      // 'velocidad' es CONTINUO, no un disparo al entrar como alPisar/impulso: manda mientras el pie
      // este encima. app.js lee mc.speed UNA vez por frame (app.js:5060) y de ahi salen tanto la
      // marcha en el suelo como la aceleracion en el aire, asi que basta con dejarlo puesto durante
      // orig(dt) y devolverlo despues. Se escribe mc.speed a pelo y NO game.playerSpeed: el setter
      // guarda en localStorage, y persistir un valor de bloque le cambiaria la marcha para siempre.
      var velPrevia = mc.speed;
      var fac = (pieAntes && pieAntes.m && pieAntes.m.cfg && pieAntes.m.cfg.velocidad) || 0;
      var objetivo = fac > 0 ? Math.min(VEL_MAX, velPrevia * fac) : velPrevia;
      // INERCIA. Sin esto, la marcha vuelve a la base EL MISMO FRAME en que el pie sale del bloque
      // rapido, y el dueño lo vio en un pasillo de hielo (velocidad:2) que termina en un trampolin:
      // basta UN bloque de suelo normal entre medias para llegar al trampolin a marcha base y salir
      // despedido sin nada de lo que habias corrido (medido: 10 -> 5 con un solo bloque de hueco).
      // Acelerar es instantaneo (pisar hielo se nota ya); FRENAR decae con exp(-dt/TAU), o sea igual
      // a 30 que a 120 fps. Ojo: esto es inercia de RAPIDEZ, no de patinaje: soltar las teclas para
      // en seco, porque en el suelo app.js:5094 pone vel=0 cuando no hay direccion. Lo otro (seguir
      // rodando al soltar) es 'deslizamiento', y va aparte en deslizar().
      // Y es marcha LLEVADA: si el jugador se ha parado de verdad, ya no lleva nada. El decaimiento
      // corria por RELOJ aunque estuvieras quieto, asi que soltar las teclas al salir del bloque te
      // paraba (bien) pero volver a pulsar W dentro de los ~3·TAU siguientes te lanzaba a media
      // marcha del bloque rapido habiendo parado antes — con ×10 son casi 3 s de arranque regalado.
      // Parado = en el suelo, sin tecla de rumbo y sin derrape en curso (si patinas SI llevas algo).
      if (mc.onGround && !hayRumbo() && !mc._deslizVel) mc._velInercia = 0;
      var llevada = mc._velInercia || 0;
      if (llevada > objetivo + 1e-6 && TAU_INERCIA > 0) {
        llevada = objetivo + (llevada - objetivo) * Math.exp(-dt / TAU_INERCIA);
        if (llevada < objetivo + 1 / 64) llevada = objetivo;   // menos de eso no se nota: se cierra
      } else {
        llevada = objetivo;
      }
      mc._velInercia = llevada;
      if (llevada !== velPrevia) mc.speed = llevada;
      try {
        orig(dt);                                         // la fisica de siempre, intacta
      } finally {
        mc.speed = velPrevia;                             // pase lo que pase, no se queda pegada
      }
      if (!mc.grid) return;
      agarradoPrev = !!((agarre && posAntes) ? aplicarTrepado(agarre, posAntes, dt) : null);
      deslizar(dt);                                     // antes de pisar: el derrape puede cambiar de celda
      pisar(pieAntes, velAntes);
      suavizarPaso(dt);                                 // lo ultimo del jugador: de aqui en adelante solo se dibuja
      mirarObjetivos(dt);                               // el mundo mirando al jugador, ya con su posicion final
    };
    envuelto._bloques = VERSION;
    envuelto._orig = orig;
    window.mcUpdate = envuelto;
    envolverMoveAxis();                                   // el segundo (y ultimo) enganche: mide el escalon
  }

  var anterior = (typeof game !== 'undefined' && game.bloques) || null;   // antes de pisarlo
  if (previo && anterior && typeof anterior.pasoSuave === 'function') {
    var tauViejo = anterior.pasoSuave();                 // lo que el dueño hubiera ajustado a mano
    if (typeof tauViejo === 'number' && isFinite(tauViejo)) TAU_PASO = tauViejo;
    if (typeof anterior.inercia === 'function') {
      var inerViejo = anterior.inercia();
      if (typeof inerViejo === 'number' && isFinite(inerViejo)) TAU_INERCIA = inerViejo;
    }
    if (typeof anterior.roce === 'function') {
      var roceViejo = anterior.roce();
      if (typeof roceViejo === 'number' && isFinite(roceViejo)) TAU_ROCE = roceViejo;
    }
  }

  game.bloques = {
    version: VERSION,
    define: define, quitar: quitar, lista: lista, info: info,
    avisos: function () { return avisos.slice(); },
    // Cuanto tarda el ojo en alcanzar al cuerpo tras un escalon, en segundos. 0 = como antes
    // (salto instantaneo). Por encima de ~0,15 se nota flotante. Sin argumento, lo consulta.
    pasoSuave: function (tau) {
      if (tau === undefined) return TAU_PASO;
      tau = Number(tau);
      if (!isFinite(tau) || tau < 0) { console.warn('game.bloques.pasoSuave: dame segundos, 0 para desactivar.'); return TAU_PASO; }
      TAU_PASO = tau;
      if (!tau && mc._pasoDesfase) { restaurarPaso(); mc._pasoDesfase = 0; }   // se apaga sin dejar al ojo hundido
      console.log('game.bloques: subida de escalon ' + (tau ? 'suavizada en ' + tau + ' s' : 'instantánea (como antes)'));
      return TAU_PASO;
    },
    // Segundos que tarda la marcha en volver a la normal al salir de un bloque con 'velocidad'.
    // 0 = como antes (se corta en seco al pisar fuera). Sin argumento, lo consulta.
    inercia: function (tau) {
      if (tau === undefined) return TAU_INERCIA;
      tau = Number(tau);
      if (!isFinite(tau) || tau < 0) { console.warn('game.bloques.inercia: dame segundos, 0 para desactivar.'); return TAU_INERCIA; }
      TAU_INERCIA = tau;
      if (!tau && typeof mc !== 'undefined') mc._velInercia = 0;
      console.log('game.bloques: la marcha ' + (tau ? 'baja en ' + tau + ' s al salir del bloque rapido' : 'vuelve a la normal en seco (como antes)'));
      return TAU_INERCIA;
    },
    // Segundos que dura el derrape una vez FUERA del bloque deslizante (encima manda el tau del
    // bloque). Corto a proposito: sales patinando, no flotando. 0 = frenazo seco al salir del hielo.
    roce: function (tau) {
      if (tau === undefined) return TAU_ROCE;
      tau = Number(tau);
      if (!isFinite(tau) || tau < 0) { console.warn('game.bloques.roce: dame segundos, 0 para desactivar.'); return TAU_ROCE; }
      TAU_ROCE = tau;
      if (!tau && typeof mc !== 'undefined') mc._deslizVel = null;
      console.log('game.bloques: al salir del bloque deslizante ' + (tau ? 'se sigue patinando ' + tau + ' s' : 'se frena en seco'));
      return TAU_ROCE;
    },
    mirones: mirones_,
    _tabla: tabla,
    _porId: function () { return porId.slice(); }         // para inspeccionar la cache densa
  };

  // ── Comportamientos por defecto de este mundo ────────────────────────────────────────────────
  // Los datos estan ARRIBA DEL TODO (DEFECTOS), que es donde se buscan cuando solo se quiere cambiar
  // el mundo; aqui abajo solo se registran, porque es donde define() ya existe y tiene tabla y cache.
  Object.keys(DEFECTOS).forEach(function (k) { define(k, DEFECTOS[k]); });

  // Lo definido A MANO en la consola sobrevive a reejecutar el snippet: los cfg guardados ya estan
  // normalizados y define() los vuelve a normalizar con el codigo de ahora, asi que valen aunque la
  // version anterior tuviera otra forma.
  // Pero SOLO se hereda lo que esta ejecucion NO ha definido: lo que acabas de escribir aqui arriba
  // MANDA. Antes se heredaba todo encima y editar un define no servia absolutamente de nada — el
  // valor nuevo entraba (el define hasta avisaba del ×30) y dos lineas despues la tabla vieja lo
  // volvia a pisar, asi que lista() seguia enseñando el valor viejo y el mundo tampoco cambiaba.
  // Ojo al reves: BORRAR un define de aqui no lo quita, porque se hereda del run anterior. Para eso,
  // game.bloques.quitar('clave') o recargar la pestaña (al recargar no hay nada que heredar).
  var heredado = (previo && anterior && anterior._tabla) || null;
  if (heredado) {
    var claves = Object.keys(heredado).filter(function (k) { return !tabla[k]; });
    claves.forEach(function (k) { define(k, heredado[k]); });
    if (claves.length) console.log('game.bloques: heredados ' + claves.length + ' material(es) definidos a mano (los del snippet mandan).');
  }

  console.log('game.bloques ' + VERSION + ' · ' + Object.keys(tabla).length + ' material(es) con comportamiento'
    + (yaEstaba ? ' (envoltorio REINSTALADO: la física ahora lee esta tabla)' : '')
    + '. game.bloques.lista() / .info()');

})();
